import React, { createContext, useContext, useState, useEffect, ReactNode } from 'react';
import { getApiBaseUrl } from '../utils/api';

// Типи для налаштувань
export interface ConnectionSettings {
  websocketUrl: string;
  websocketPort: number;
  apiEndpoint: string;
  connectionTimeout: number;
  reconnectInterval: number;
  maxReconnectAttempts: number;
}

export interface NotificationSettings {
  enableDesktopNotifications: boolean;
  enableSoundNotifications: boolean;
  alertThreshold: number;
  muteHours: { start: string; end: string };
}

export interface DisplaySettings {
  theme: 'light' | 'dark' | 'auto';
  language: 'en' | 'uk';
  refreshInterval: number;
  showAdvancedMetrics: boolean;
  compactView: boolean;
}

export interface Settings {
  connection: ConnectionSettings;
  notifications: NotificationSettings;
  display: DisplaySettings;
}

// Стан налаштувань
interface SettingsState {
  settings: Settings;
  isLoading: boolean;
  error: string | null;
}

// Контекст налаштувань
interface SettingsContextType {
  state: SettingsState;
  updateSettings: (newSettings: Partial<Settings>) => void;
  resetSettings: () => void;
  saveSettings: () => Promise<void>;
}

// Значення за замовчуванням
const defaultSettings: Settings = {
  connection: {
    websocketUrl: 'ws://localhost',
    websocketPort: 8000,
    apiEndpoint: getApiBaseUrl(),
    connectionTimeout: 5000,
    reconnectInterval: 3000,
    maxReconnectAttempts: 5,
  },
  notifications: {
    enableDesktopNotifications: true,
    enableSoundNotifications: true,
    alertThreshold: 80,
    muteHours: { start: '00:00', end: '08:00' },
  },
  display: {
    theme: 'auto',
    language: 'uk',
    refreshInterval: 5000,
    showAdvancedMetrics: true,
    compactView: false,
  },
};

const SettingsContext = createContext<SettingsContextType | undefined>(undefined);

export const useSettings = (): SettingsContextType => {
  const context = useContext(SettingsContext);
  if (!context) {
    throw new Error('useSettings must be used within a SettingsProvider');
  }
  return context;
};

interface SettingsProviderProps {
  children: ReactNode;
}

export const SettingsProvider: React.FC<SettingsProviderProps> = ({ children }) => {
  const [state, setState] = useState<SettingsState>({
    settings: defaultSettings,
    isLoading: true,
    error: null,
  });

  const updateSettings = (newSettings: Partial<Settings>) => {
    setState(prev => ({
      ...prev,
      settings: {
        ...prev.settings,
        ...newSettings,
      },
    }));
  };

  const resetSettings = () => {
    setState(prev => ({
      ...prev,
      settings: defaultSettings,
    }));
  };

  const saveSettings = async () => {
    try {
      localStorage.setItem('tetracore-settings', JSON.stringify(state.settings));
    } catch (error) {
      console.error('Failed to save settings:', error);
    }
  };

  const loadSettings = () => {
    try {
      const saved = localStorage.getItem('tetracore-settings');
      if (saved) {
        const parsed = JSON.parse(saved);
        setState(prev => ({
          ...prev,
          settings: { ...defaultSettings, ...parsed },
          isLoading: false,
        }));
      }
    } catch (error) {
      console.error('Failed to load settings:', error);
    }
  };

  useEffect(() => {
    loadSettings();
  }, []);

  useEffect(() => {
    saveSettings();
  }, [state.settings]);

  const value: SettingsContextType = {
    state,
    updateSettings,
    resetSettings,
    saveSettings,
  };

  return (
    <SettingsContext.Provider value={value}>
      {children}
    </SettingsContext.Provider>
  );
};
